        vm.assume(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        vm.prank(caller);
        bool ok;
        try c.setL1BlockValues(1, 2, 3, bytes32(0), 4, bytes32(0), 5, 6) {
