}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_,
        address actor
    ) public {
        vm.assume(actor != c.depositorAccount());
        vm.prank(actor);
        try c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_) {
            assertTrue(false, "non-depositor call must revert");
        } catch {
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) external {
        require(c.depositorAccount() != address(this), "must be non-depositor");
        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                n, t, f, h, s, b, o, sc
            )
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(
        uint64 n,
        uint64 t,
        uint256 f,
        bytes32 h,
        uint64 s,
        bytes32 b,
        uint256 o,
        uint256 sc
    ) external {
        bool reverted = false;
        // state-changing call as its own top-level statement inside try/catch is forbidden,
        // so use low-level style via try is not allowed; instead detect revert via return data trick:
        // We call through c using a try wrapper is disallowed; use low-level call on address(c).
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                n, t, f, h, s, b, o, sc
            )
        );
        reverted = !ok;
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}
